/**
 * Set up contour source/layers on the map (synchronous, fast).
 * Must be called after survey lines are added so we can insert before them.
 */
function setupContourLayers() {
    // Add empty contours source
    map.addSource('contours-source', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    // Add contour line layer
    map.addLayer({
        id: 'contours-layer',
        type: 'line',
        source: 'contours-source',
        paint: {
            'line-color': CONFIG.CONTOUR_COLOR,
            'line-width': [
                'case',
                ['==', ['%', ['get', 'depth'], 5], 0],
                2,
                1
            ],
            'line-opacity': 0.6
        },
        layout: {
            visibility: state.layerVisibility.contours ? 'visible' : 'none'
        },
        minzoom: Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))
    }, 'survey-lines-layer');

    // Add contour labels
    map.addLayer({
        id: 'contours-labels',
        type: 'symbol',
        source: 'contours-source',
        paint: {
            'text-color': CONFIG.CONTOUR_COLOR,
            'text-halo-color': '#ffffff',
            'text-halo-width': 2,
            'text-opacity': 0.9
        },
        layout: {
            'text-field': ['concat', ['get', 'depth'], 'm'],
            'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
            'text-size': 11,
            'symbol-placement': 'line-center',
            'text-rotation-alignment': 'map',
            'text-pitch-alignment': 'viewport',
            'text-max-angle': 45,
            'text-padding': 1,
            'symbol-sort-key': ['case',
                ['==', ['%', ['get', 'depth'], 5], 0], 0,
                1
            ],
            visibility: state.layerVisibility.contours ? 'visible' : 'none'
        },
        minzoom: Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))
    }, 'survey-lines-layer');

    // Regenerate contours on map movement (after debounce)
    map.on('moveend', debounce(generateContoursForViewport, 300));
}

/**
 * Load the pre-processed contour source (small, pre-smoothed) and read the
 * entire grid into memory once. This replaces the expensive per-viewport
 * readRasters from the full bathymetry COG.
 * Designed to run in the background — does NOT block loading overlay.
 */
async function initializeContourGeneration() {
    try {
        console.time('⏱️ contour: load contour source');
        const tiff = await GeoTIFF.fromUrl(CONFIG.CONTOUR_COG, {
            allowFullFile: false,  // File is now ~2-4MB with overviews, use range requests
            cacheSize: 100
        });

        // Store tiff reference for high-zoom viewport reads
        state.contourTiff = tiff;

        const image = await tiff.getImage();
        const nativeWidth = image.getWidth();
        const nativeHeight = image.getHeight();
        const bbox = image.getBoundingBox(); // [minX, minY, maxX, maxY] EPSG:3857
        const noData = image.getFileDirectory().GDAL_NODATA;
        const noDataValue = noData !== undefined ? parseFloat(noData) : -9999;

        state.contourNoData = noDataValue;
        state.contourBbox = bbox;

        // Read smallest overview into memory (~512×1191) for fast sync contours at low zoom
        // tiff.readRasters auto-selects the best overview for the requested size
        const lowWidth = Math.round(nativeWidth / 4);
        const lowHeight = Math.round(nativeHeight / 4);
        const rasters = await tiff.readRasters({ width: lowWidth, height: lowHeight });
        const rawGrid = rasters[0];

        // Clean NoData → NaN
        const grid = new Float32Array(rawGrid.length);
        for (let i = 0; i < rawGrid.length; i++) {
            const val = rawGrid[i];
            if (val === noDataValue || val >= 1e5 || !Number.isFinite(val)) {
                grid[i] = Number.NaN;
            } else {
                grid[i] = val;
            }
        }

        // Store low-res overview for sync contour generation
        state.contourLowRes = { grid, width: lowWidth, height: lowHeight, bbox };
        console.timeEnd('⏱️ contour: load contour source');
        console.log(`Contour source loaded: native ${nativeWidth}×${nativeHeight}, low-res ${lowWidth}×${lowHeight}, ${(rawGrid.length * 4 / 1024).toFixed(0)}KB`);

        // Generate initial contours now that the data is ready
        if (map.getZoom() >= Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number))) {
            console.time('⏱️ contour: generateContoursForViewport (initial)');
            generateContoursForViewport();
            console.timeEnd('⏱️ contour: generateContoursForViewport (initial)');
        }

    } catch (error) {
        console.error('Failed to initialize contour generation:', error);
    }
}

/**
 * Web Mercator to WGS84 conversion
 */
function webMercatorToLngLat(x, y) {
    const lng = (x / 20037508.34) * 180;
    let lat = (y / 20037508.34) * 180;
    lat = (180 / Math.PI) * (2 * Math.atan(Math.exp((lat * Math.PI) / 180)) - Math.PI / 2);
    return [lng, lat];
}

/**
 * WGS84 to Web Mercator conversion
 */
function lngLatToWebMercator(lng, lat) {
    const x = (lng / 180) * 20037508.34;
    const y = Math.log(Math.tan((90 + lat) * Math.PI / 360)) / (Math.PI / 180);
    return [x, (y / 180) * 20037508.34];
}

/**
 * Generate contour GeoJSON from a grid + bbox.
 *
 * d3.contours produces closed polygon rings. When an isoline hits the NoData
 * boundary it gets "closed" by tracing along the boundary edge. These boundary
 * segments appear at every threshold. We identify them by collecting all
 * pixel-space coordinates from the deepest threshold's rings (which are purely
 * boundary), then stripping those coordinates from rings at other depths.
 * What remains are the real interior isoline segments.
 */
function generateContourGeoJSON(grid, width, height, bbox, waterLevel, interval) {
    const maxContourDepth = Math.round(waterLevel - CONFIG.MIN_ELEVATION_AHD);
    const thresholds = [];
    for (let depth = interval; depth <= maxContourDepth; depth += interval) {
        const ahdLevel = waterLevel - depth;
        if (ahdLevel >= CONFIG.MIN_ELEVATION_AHD) {
            thresholds.push(ahdLevel);
        }
    }

    const contourGenerator = d3.contours()
        .size([width, height])
        .thresholds(thresholds)
        .smooth(true);

    const contourMultiPolygons = contourGenerator(grid);

    // --- Pass 1: find the deepest threshold and collect its boundary coords ---
    let deepestAHD = Infinity;
    for (const mp of contourMultiPolygons) {
        if (mp.coordinates.length > 0 && mp.value < deepestAHD) {
            deepestAHD = mp.value;
        }
    }
    const deepestDepth = Math.round(waterLevel - deepestAHD);

    // Build a Set of pixel-coordinate keys from the deepest rings
    const boundaryCoords = new Set();
    for (const mp of contourMultiPolygons) {
        if (mp.value !== deepestAHD) continue;
        for (const polygon of mp.coordinates) {
            for (const ring of polygon) {
                for (const [x, y] of ring) {
                    // Key at ~0.01 pixel precision to handle smoothing
                    boundaryCoords.add(`${(x * 100) | 0},${(y * 100) | 0}`);
                }
            }
        }
    }

    // --- Pass 2: build features, stripping boundary coordinates ---
    const pixelToGeo = (x, y) => {
        const mercatorX = bbox[0] + (x / width) * (bbox[2] - bbox[0]);
        const mercatorY = bbox[3] - (y / height) * (bbox[3] - bbox[1]);
        return webMercatorToLngLat(mercatorX, mercatorY);
    };

    const features = [];

    for (const multiPolygon of contourMultiPolygons) {
        if (multiPolygon.coordinates.length === 0) continue;

        const ahdLevel = multiPolygon.value;
        const depth = Math.round(waterLevel - ahdLevel);
        if (depth <= 0) continue;

        // Drop the deepest threshold entirely (purely boundary)
        if (depth === deepestDepth) continue;

        for (const polygon of multiPolygon.coordinates) {
            for (const ring of polygon) {
                if (ring.length < 10) continue;

                // Split ring into segments by removing boundary points
                let currentSegment = [];
                for (const [x, y] of ring) {
                    const key = `${(x * 100) | 0},${(y * 100) | 0}`;
                    if (boundaryCoords.has(key)) {
                        // Flush current segment if long enough
                        if (currentSegment.length >= 5) {
                            features.push({
                                type: 'Feature',
                                properties: { depth, ahdLevel, interval },
                                geometry: {
                                    type: 'LineString',
                                    coordinates: currentSegment.map(
                                        ([px, py]) => pixelToGeo(px, py)
                                    )
                                }
                            });
                        }
                        currentSegment = [];
                    } else {
                        currentSegment.push([x, y]);
                    }
                }
                // Flush final segment
                if (currentSegment.length >= 5) {
                    features.push({
                        type: 'Feature',
                        properties: { depth, ahdLevel, interval },
                        geometry: {
                            type: 'LineString',
                            coordinates: currentSegment.map(
                                ([px, py]) => pixelToGeo(px, py)
                            )
                        }
                    });
                }
            }
        }
    }

    return { type: 'FeatureCollection', features };
}

/**
 * Download the current contour GeoJSON for analysis.
 * Call from the browser console: downloadContourGeoJSON()
 */
globalThis.downloadContourGeoJSON = function () {
    if (!state.lastContourGeoJSON) {
        console.warn('No contour data available — zoom in to generate contours first');
        return;
    }
    const data = state.lastContourGeoJSON;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `contours_z${Math.floor(map.getZoom())}.geojson`;
    a.click();
    URL.revokeObjectURL(url);
    console.log(`Downloaded ${data.features.length} features`);
};

function generateContoursForViewport() {
    if (!state.contourLowRes) return;
    if (!state.layerVisibility.contours) return;

    const zoom = Math.floor(map.getZoom());
    const minContourZoom = Math.min(...Object.keys(CONFIG.CONTOUR_INTERVALS).map(Number));
    if (zoom < minContourZoom) return;

    const bounds = map.getBounds();

    // Determine contour interval
    let interval = 10;
    for (const [zoomThreshold, int] of Object.entries(CONFIG.CONTOUR_INTERVALS).sort((a, b) => b[0] - a[0])) {
        if (zoom >= parseInt(zoomThreshold)) {
            interval = int;
            break;
        }
    }

    const waterLevel = getActiveWaterLevel();
    const tier = zoom >= 16 ? 'hi' : 'lo';
    const cacheKey = `${tier}-${zoom}-${interval}-${waterLevel.toFixed(1)}-${bounds.toString()}`;

    if (state.contoursCache.has(cacheKey)) {
        state.lastContourGeoJSON = state.contoursCache.get(cacheKey);
        map.getSource('contours-source').setData(state.lastContourGeoJSON);
        return;
    }

    if (zoom < 16) {
        // Synchronous: use cached low-res grid
        console.time('⏱️ contour: generate (low-res)');
        try {
            const { grid, width, height, bbox } = state.contourLowRes;
            const geojson = generateContourGeoJSON(grid, width, height, bbox, waterLevel, interval);
            state.lastContourGeoJSON = geojson;

            if (map.getSource('contours-source')) {
                map.getSource('contours-source').setData(geojson);
            }

            if (state.contoursCache.size > 20) {
                const firstKey = state.contoursCache.keys().next().value;
                state.contoursCache.delete(firstKey);
            }
            state.contoursCache.set(cacheKey, geojson);
        } catch (error) {
            console.error('Failed to generate contours (low-res):', error);
        }
        console.timeEnd('⏱️ contour: generate (low-res)');
    } else {
        // First show low-res contours immediately, then async fetch hi-res
        try {
            const { grid, width, height, bbox } = state.contourLowRes;
            const loGeojson = generateContourGeoJSON(grid, width, height, bbox, waterLevel, interval);
            if (map.getSource('contours-source')) {
                map.getSource('contours-source').setData(loGeojson);
            }
        } catch (e) {
            // Non-critical, hi-res will replace
        }

        // Async high-res viewport read
        generateHighResContours(bounds, waterLevel, interval, cacheKey);
    }
}

/**
 * Async high-resolution contour generation for zoom >= 16.
 * Reads only the viewport extent from the COG at appropriate resolution.
 */
async function generateHighResContours(bounds, waterLevel, interval, cacheKey) {
    if (!state.contourTiff || !state.contourBbox) return;

    const token = ++state.contourGenToken;

    try {
        console.time('⏱️ contour: generate (hi-res)');

        // Convert map viewport bounds from WGS84 → EPSG:3857
        const sw = lngLatToWebMercator(bounds.getWest(), bounds.getSouth());
        const ne = lngLatToWebMercator(bounds.getEast(), bounds.getNorth());

        // Expand by 50% (same as hillshade) so panning doesn't show edges
        const padX = (ne[0] - sw[0]) * 0.5;
        const padY = (ne[1] - sw[1]) * 0.5;

        // Clamp expanded viewport to contour source extent
        const [srcMinX, srcMinY, srcMaxX, srcMaxY] = state.contourBbox;
        const bboxMinX = Math.max(sw[0] - padX, srcMinX);
        const bboxMinY = Math.max(sw[1] - padY, srcMinY);
        const bboxMaxX = Math.min(ne[0] + padX, srcMaxX);
        const bboxMaxY = Math.min(ne[1] + padY, srcMaxY);

        // Skip if viewport doesn't overlap the source
        if (bboxMinX >= bboxMaxX || bboxMinY >= bboxMaxY) {
            console.timeEnd('⏱️ contour: generate (hi-res)');
            return;
        }

        const bbox = [bboxMinX, bboxMinY, bboxMaxX, bboxMaxY];

        // Calculate resolution: ~1 pixel per 2m for detailed contours
        const resX = 2.0;  // 2 metres per pixel
        const resY = 2.0;

        const rasters = await state.contourTiff.readRasters({
            bbox,
            resX,
            resY
        });

        // Check if this read is stale
        if (token !== state.contourGenToken) {
            console.timeEnd('⏱️ contour: generate (hi-res)');
            return;
        }

        const rawGrid = rasters[0];
        const width = rasters.width;
        const height = rasters.height;

        // Clean NoData → NaN
        const grid = new Float32Array(rawGrid.length);
        const noDataValue = state.contourNoData;
        for (let i = 0; i < rawGrid.length; i++) {
            const val = rawGrid[i];
            if (val === noDataValue || val >= 1e5 || !Number.isFinite(val)) {
                grid[i] = Number.NaN;
            } else {
                grid[i] = val;
            }
        }

        // Check stale again after processing
        if (token !== state.contourGenToken) {
            console.timeEnd('⏱️ contour: generate (hi-res)');
            return;
        }

        const geojson = generateContourGeoJSON(grid, width, height, bbox, waterLevel, interval);
        state.lastContourGeoJSON = geojson;

        if (map.getSource('contours-source')) {
            map.getSource('contours-source').setData(geojson);
        }

        // Cache with limit
        if (state.contoursCache.size > 20) {
            const firstKey = state.contoursCache.keys().next().value;
            state.contoursCache.delete(firstKey);
        }
        state.contoursCache.set(cacheKey, geojson);

        console.timeEnd('⏱️ contour: generate (hi-res)');
    } catch (error) {
        console.error('Failed to generate contours (hi-res):', error);
    }
}

// ============================================
// A* Contour Pathfinding
// ============================================

/**
 * MinHeap (binary heap) for A* open set.
 * Sorts by f-score, with h-score as tie-breaker.
 */
class MinHeap {
    constructor() {
        this.heap = [];
    }

    push(node) {
        this.heap.push(node);
        this._bubbleUp(this.heap.length - 1);
    }

    pop() {
        if (this.heap.length === 0) return null;
        const min = this.heap[0];
        const last = this.heap.pop();
        if (this.heap.length > 0) {
            this.heap[0] = last;
            this._bubbleDown(0);
        }
        return min;
    }

    isEmpty() {
        return this.heap.length === 0;
    }

    _compare(a, b) {
        if (a.f !== b.f) return a.f < b.f;
        return a.h < b.h;
    }

    _bubbleUp(index) {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (!this._compare(this.heap[index], this.heap[parentIndex])) break;
            [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];
            index = parentIndex;
        }
    }

    _bubbleDown(index) {
        while (true) {
            let left = 2 * index + 1;
            let right = 2 * index + 2;
            let smallest = index;
            if (left < this.heap.length && this._compare(this.heap[left], this.heap[smallest])) {
                smallest = left;
            }
            if (right < this.heap.length && this._compare(this.heap[right], this.heap[smallest])) {
                smallest = right;
            }
            if (smallest === index) break;
            [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
            index = smallest;
        }
    }
}

/**
 * Ramer-Douglas-Peucker path simplification.
 * @param {Array} path - Array of [lng, lat] coordinates
 * @param {number} epsilon - Tolerance in degrees (~0.00005 ≈ 5m)
 * @returns {Array} Simplified path
 */
function simplifyPathRDP(path, epsilon = 0.00005) {
    if (path.length <= 2) return path;

    let maxDist = 0;
    let maxIndex = 0;
    const start = path[0];
    const end = path[path.length - 1];

    for (let i = 1; i < path.length - 1; i++) {
        const dist = _pointToLineDistance(path[i], start, end);
        if (dist > maxDist) {
            maxDist = dist;
            maxIndex = i;
        }
    }

    if (maxDist > epsilon) {
        const left = simplifyPathRDP(path.slice(0, maxIndex + 1), epsilon);
        const right = simplifyPathRDP(path.slice(maxIndex), epsilon);
        return left.slice(0, -1).concat(right);
    }

    return [start, end];
}

function _pointToLineDistance(point, lineStart, lineEnd) {
    const [px, py] = point;
    const [x1, y1] = lineStart;
    const [x2, y2] = lineEnd;

    const C = x2 - x1;
    const D = y2 - y1;
    const lenSq = C * C + D * D;
    let param = lenSq !== 0 ? ((px - x1) * C + (py - y1) * D) / lenSq : -1;

    let xx, yy;
    if (param < 0) { xx = x1; yy = y1; }
    else if (param > 1) { xx = x2; yy = y2; }
    else { xx = x1 + param * C; yy = y1 + param * D; }

    const dx = px - xx;
    const dy = py - yy;
    return Math.sqrt(dx * dx + dy * dy);
}

/**
 * A* contour pathfinding on a Float32 elevation grid.
 * Finds a path between two points that stays close to a target elevation.
 *
 * @param {Float32Array} grid - Elevation values (AHD), row-major
 * @param {number} width - Grid width in pixels
 * @param {number} height - Grid height in pixels
 * @param {Array} bbox - [minX, minY, maxX, maxY] in EPSG:3857
 * @param {number} startLng - Start longitude (WGS84)
 * @param {number} startLat - Start latitude (WGS84)
 * @param {number} endLng - End longitude (WGS84)
 * @param {number} endLat - End latitude (WGS84)
 * @param {number} targetElevation - Target AHD elevation to follow
 * @param {number} tolerance - Max elevation deviation in meters (default 0.5)
 * @returns {Array|null} Array of [lng, lat] coordinates, or null if no path
 */
function findContourPath(grid, width, height, bbox, startLng, startLat, endLng, endLat, targetElevation, tolerance = 0.5) {
    const totalPixels = width * height;

    // Convert lng/lat to grid coordinates via Web Mercator
    const toGrid = (lng, lat) => {
        const [mx, my] = lngLatToWebMercator(lng, lat);
        const x = Math.floor((mx - bbox[0]) / (bbox[2] - bbox[0]) * width);
        const y = Math.floor((bbox[3] - my) / (bbox[3] - bbox[1]) * height);
        return [x, y];
    };

    const fromGrid = (x, y) => {
        const mx = bbox[0] + (x / width) * (bbox[2] - bbox[0]);
        const my = bbox[3] - (y / height) * (bbox[3] - bbox[1]);
        return webMercatorToLngLat(mx, my);
    };

    const [startX, startY] = toGrid(startLng, startLat);
    const [endX, endY] = toGrid(endLng, endLat);

    // Bounds checking
    if (startX < 0 || startX >= width || startY < 0 || startY >= height ||
        endX < 0 || endX >= width || endY < 0 || endY >= height) {
        return null;
    }

    // Straight-line distance for iteration limit
    const straightDist = Math.sqrt((endX - startX) ** 2 + (endY - startY) ** 2);
    const maxIterations = Math.min(50000, Math.max(5000, Math.ceil(straightDist * 100)));

    // TypedArrays for O(1) access, no GC
    const visited = new Uint8Array(totalPixels);
    const gScores = new Float32Array(totalPixels);
    gScores.fill(Infinity);

    const startIdx = startY * width + startX;
    gScores[startIdx] = 0;

    const minHeap = new MinHeap();
    const startH = Math.sqrt((startX - endX) ** 2 + (startY - endY) ** 2);
    minHeap.push({ x: startX, y: startY, idx: startIdx, g: 0, h: startH, f: startH, parent: null });

    let iterations = 0;

    // 8-directional neighbor offsets
    const neighborOffsets = [
        { dx: -1, dy: -1, cost: 1.414 }, { dx: 0, dy: -1, cost: 1 }, { dx: 1, dy: -1, cost: 1.414 },
        { dx: -1, dy: 0, cost: 1 },                                    { dx: 1, dy: 0, cost: 1 },
        { dx: -1, dy: 1, cost: 1.414 },  { dx: 0, dy: 1, cost: 1 },  { dx: 1, dy: 1, cost: 1.414 }
    ];

    while (!minHeap.isEmpty() && iterations++ < maxIterations) {
        const current = minHeap.pop();

        if (visited[current.idx] === 1) continue;
        visited[current.idx] = 1;

        // Goal reached? (within 2 grid cells)
        if (Math.abs(current.x - endX) <= 2 && Math.abs(current.y - endY) <= 2) {
            const path = [];
            let node = current;
            while (node) {
                path.unshift(fromGrid(node.x, node.y));
                node = node.parent;
            }
            path[0] = [startLng, startLat];
            path[path.length - 1] = [endLng, endLat];
            return simplifyPathRDP(path);
        }

        for (let i = 0; i < 8; i++) {
            const { dx, dy, cost } = neighborOffsets[i];
            const nx = current.x + dx;
            const ny = current.y + dy;

            if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;

            const nIdx = ny * width + nx;
            if (visited[nIdx] === 1) continue;

            const elevation = grid[nIdx];
            if (!Number.isFinite(elevation)) continue;

            const diff = Math.abs(elevation - targetElevation);
            if (diff > tolerance) continue;

            // Depth penalty: encourage staying exactly on contour
            const depthPenalty = (diff / tolerance) * 2.0;

            // Directness penalty: small cost for moves away from goal
            const goalDx = endX - current.x;
            const goalDy = endY - current.y;
            const goalDist = Math.sqrt(goalDx * goalDx + goalDy * goalDy);
            let directnessPenalty = 0;
            if (goalDist > 0) {
                const dot = (dx * goalDx + dy * goalDy) / (Math.sqrt(dx * dx + dy * dy) * goalDist);
                directnessPenalty = (1 - dot) * 0.25;
            }

            const g = current.g + cost + depthPenalty + directnessPenalty;

            if (g < gScores[nIdx]) {
                gScores[nIdx] = g;
                const h = Math.sqrt((nx - endX) ** 2 + (ny - endY) ** 2);
                minHeap.push({ x: nx, y: ny, idx: nIdx, g, h, f: g + h, parent: current });
            }
        }
    }

    return null; // No path found
}

// ============================================
// Measure Tool
// ============================================

function initializeMeasureTool() {
    const measureBtn = document.getElementById('measure-btn');
    const clearBtn = document.getElementById('clear-btn');

    measureBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        state.measureMode = !state.measureMode;
        measureBtn.classList.toggle('active', state.measureMode);

        if (state.measureMode) {
            // Deactivate depth probe if active
            if (state.depthProbeMode) {
                state.depthProbeMode = false;
                document.getElementById('depth-probe-btn').classList.remove('active');
                document.body.classList.remove('depth-probe-active');
                if (state.depthProbeTooltip) state.depthProbeTooltip.style.display = 'none';
                hideDepthProbePopup();
            }
            document.body.classList.add('measure-mode-active');
            clearBtn.style.display = 'block';
            if (map.getLayer('survey-vertices-layer')) {
                map.setLayoutProperty('survey-vertices-layer', 'visibility', 'visible');
            }
        } else {
            document.body.classList.remove('measure-mode-active');
            clearMeasurements();
            if (map.getLayer('survey-vertices-layer')) {
                map.setLayoutProperty('survey-vertices-layer', 'visibility', 'none');
            }
        }

        measureBtn.blur();
    });

    clearBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        clearMeasurements();
    });

    // Add measure sources
    map.addSource('measure-line', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    map.addSource('measure-points', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    map.addLayer({
        id: 'measure-line-layer',
        type: 'line',
        source: 'measure-line',
        paint: {
            'line-color': '#0891b2',
            'line-width': 3,
            'line-dasharray': [2, 2]
        }
    });

    // Invisible wider hit-target for line drag detection
    map.addLayer({
        id: 'measure-line-hit',
        type: 'line',
        source: 'measure-line',
        paint: {
            'line-color': 'transparent',
            'line-width': 16
        }
    });

    // Contour preview layer (shown during contour drag)
    map.addSource('measure-contour-preview', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] }
    });

    map.addLayer({
        id: 'measure-contour-preview-layer',
        type: 'line',
        source: 'measure-contour-preview',
        paint: {
            'line-color': '#06b6d4',
            'line-width': 3,
            'line-opacity': 0.8
        }
    });

    map.addLayer({
        id: 'measure-points-layer',
        type: 'circle',
        source: 'measure-points',
        paint: {
            'circle-radius': ['case', ['get', 'isContourAnchor'], 4, 6],
            'circle-color': ['case', ['get', 'isContourAnchor'], '#06b6d4', '#0891b2'],
            'circle-stroke-color': '#ffffff',
            'circle-stroke-width': 2
        }
    });
}

function clearMeasurements() {
    state.measurePoints = [];
    state.measureSegments = [];
    state.measureTotalDistance = 0;
    state.lastMeasureVertexKey = null;
    state.draggingPointIndex = null;
    state._suppressClick = false;
    state.draggingContourSegment = null;
    state.contourDragGrid = null;
    state.contourPreviewCoords = null;

    document.getElementById('measure-panel').style.display = 'none';
    document.getElementById('measure-total').textContent = '0 m';
    document.getElementById('measure-items').innerHTML = '';

    map.getSource('measure-line').setData({ type: 'FeatureCollection', features: [] });
    map.getSource('measure-points').setData({ type: 'FeatureCollection', features: [] });
    map.getSource('survey-vertex-highlight').setData({ type: 'FeatureCollection', features: [] });
    map.getSource('measure-contour-preview').setData({ type: 'FeatureCollection', features: [] });

    // Clear elevation profile
    const profileEl = document.getElementById('measure-profile');
    if (profileEl) {
        profileEl.classList.remove('visible');
        profileEl.innerHTML = '';
    }
}

/**
 * Add a vertex-type point to the measure route (clicked on a survey vertex).
 */
function addMeasureVertex(clickedKey) {
    const [lng, lat] = coordFromKey(clickedKey);
    const point = { lng, lat, isVertex: true, vertexKey: clickedKey };

    let segmentDistance = 0;
    let segmentCoords = null;
    let segmentBearing = null;

    if (state.measurePoints.length > 0) {
        const prev = state.measurePoints[state.measurePoints.length - 1];

        if (prev.isVertex && prev.vertexKey && state.lastMeasureVertexKey) {
            // Previous was a vertex → route along graph
            const result = findShortestPath(state.lastMeasureVertexKey, clickedKey);
            if (result) {
                segmentCoords = result.path.map(k => coordFromKey(k));
                segmentDistance = result.distance;
                segmentBearing = 'line';
            } else {
                // No graph path — fall back to straight line
                segmentCoords = [[prev.lng, prev.lat], [lng, lat]];
                segmentDistance = haversineDistance([prev.lng, prev.lat], [lng, lat]);
                segmentBearing = bearing([prev.lng, prev.lat], [lng, lat]);
            }
        } else {
            // Previous was free-form → straight line to this vertex
            segmentCoords = [[prev.lng, prev.lat], [lng, lat]];
            segmentDistance = haversineDistance([prev.lng, prev.lat], [lng, lat]);
            segmentBearing = bearing([prev.lng, prev.lat], [lng, lat]);
        }

        state.measureSegments.push({ coords: segmentCoords, distance: segmentDistance });
    }

    state.measurePoints.push(point);
    state.lastMeasureVertexKey = clickedKey;
    state.measureTotalDistance += segmentDistance;

    updateMeasurePanel(segmentDistance, segmentBearing);
    updateMeasureVisualization();
    updateVertexHighlights();
}

/**
 * Add a free-form point to the measure route (clicked on empty map).
 */
function addMeasureFreePoint(lngLat) {
    const point = { lng: lngLat.lng, lat: lngLat.lat, isVertex: false, vertexKey: null };

    let segmentDistance = 0;
    let segmentBearing = null;

    if (state.measurePoints.length > 0) {
        const prev = state.measurePoints[state.measurePoints.length - 1];
        const segmentCoords = [[prev.lng, prev.lat], [lngLat.lng, lngLat.lat]];
        segmentDistance = haversineDistance([prev.lng, prev.lat], [lngLat.lng, lngLat.lat]);
        segmentBearing = bearing([prev.lng, prev.lat], [lngLat.lng, lngLat.lat]);
        state.measureSegments.push({ coords: segmentCoords, distance: segmentDistance });
    }

    state.measurePoints.push(point);
    state.lastMeasureVertexKey = null;
    state.measureTotalDistance += segmentDistance;

    updateMeasurePanel(segmentDistance, segmentBearing);
    updateMeasureVisualization();
}

/**
 * Update the measure panel with the latest point.
 */
function updateMeasurePanel(segmentDistance, segmentBearing) {
    const measurePanel = document.getElementById('measure-panel');
    const measureTotal = document.getElementById('measure-total');
    const measureItems = document.getElementById('measure-items');

    const idx = state.measurePoints.length;
    const displayName = idx === 1 ? 'Start point' : `Point ${idx}`;

    measurePanel.style.display = 'block';
    measureTotal.textContent = formatDistance(state.measureTotalDistance);

    const bearingHtml = segmentBearing === 'line'
        ? `<span class="measure-item-bearing">line</span>`
        : segmentBearing !== null
            ? `<span class="measure-item-bearing">${Math.round(segmentBearing)}°</span>`
            : '';

    const itemEl = document.createElement('div');
    itemEl.className = 'measure-item';
    itemEl.innerHTML = `
        <span class="measure-item-name">
            <span class="measure-item-dot" style="background: #0891b2;"></span>
            ${displayName}
        </span>
        <span class="measure-item-info">
            ${bearingHtml}
            <span class="measure-item-distance">${formatDistance(segmentDistance)}</span>
        </span>
    `;
    measureItems.appendChild(itemEl);
    updateElevationProfile();
}

/**
 * Full rebuild of the measure panel from current measurePoints and measureSegments.
 * Needed when dragging changes distances/bearings of existing entries.
 */
function rebuildMeasurePanel() {
    const measurePanel = document.getElementById('measure-panel');
    const measureTotal = document.getElementById('measure-total');
    const measureItems = document.getElementById('measure-items');

    measureItems.innerHTML = '';

    if (state.measurePoints.length === 0) {
        measurePanel.style.display = 'none';
        return;
    }

    measurePanel.style.display = 'block';
    measureTotal.textContent = formatDistance(state.measureTotalDistance);

    for (let i = 0; i < state.measurePoints.length; i++) {
        const displayName = i === 0 ? 'Start point' : `Point ${i + 1}`;
        let bearingHtml = '';

        if (i > 0) {
            const prev = state.measurePoints[i - 1];
            const curr = state.measurePoints[i];
            const seg = state.measureSegments[i - 1];

            // Determine segment display type
            if (seg.contourAHD !== undefined) {
                // Contour segment: show depth label
                const contourDepth = getActiveWaterLevel() - seg.contourAHD;
                bearingHtml = `<span class="measure-item-bearing">${contourDepth.toFixed(1)}m contour</span>`;
            } else if (prev.isVertex && curr.isVertex && seg.coords.length > 2) {
                // Graph-routed segment
                bearingHtml = `<span class="measure-item-bearing">line</span>`;
            } else {
                const b = bearing([prev.lng, prev.lat], [curr.lng, curr.lat]);
                bearingHtml = `<span class="measure-item-bearing">${Math.round(b)}°</span>`;
            }
        }

        const segDist = i > 0 ? state.measureSegments[i - 1].distance : 0;
        const itemEl = document.createElement('div');
        itemEl.className = 'measure-item';
        itemEl.innerHTML = `
            <span class="measure-item-name">
                <span class="measure-item-dot" style="background: #0891b2;"></span>
                ${displayName}
            </span>
            <span class="measure-item-info">
                ${bearingHtml}
                <span class="measure-item-distance">${formatDistance(segDist)}</span>
            </span>
        `;
        measureItems.appendChild(itemEl);
    }
    updateElevationProfile();
}

/**
 * Update highlighted vertices (all selected vertex-type points).
 */
function updateVertexHighlights() {
    const features = state.measurePoints
        .filter(p => p.isVertex)
        .map(p => ({
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [p.lng, p.lat] },
            properties: {}
        }));

    map.getSource('survey-vertex-highlight').setData({
        type: 'FeatureCollection',
        features
    });
}

function updateMeasureVisualization() {
    // Point markers for all measure points
    const pointFeatures = state.measurePoints.map((point, index) => ({
        type: 'Feature',
        geometry: {
            type: 'Point',
            coordinates: [point.lng, point.lat]
        },
        properties: { index, isVertex: point.isVertex, isContourAnchor: !!point.isContourAnchor }
    }));

    map.getSource('measure-points').setData({
        type: 'FeatureCollection',
        features: pointFeatures
    });

    // Concatenate all segment coords into one continuous line
    if (state.measureSegments.length > 0) {
        let allCoords = [];
        for (const seg of state.measureSegments) {
            if (allCoords.length === 0) {
                allCoords = [...seg.coords];
            } else {
                // Skip first coord of segment (same as last of previous)
                allCoords.push(...seg.coords.slice(1));
            }
        }

        map.getSource('measure-line').setData({
            type: 'FeatureCollection',
            features: [{
                type: 'Feature',
                geometry: {
                    type: 'LineString',
                    coordinates: allCoords
                },
                properties: {}
            }]
        });
    } else {
        map.getSource('measure-line').setData({ type: 'FeatureCollection', features: [] });
    }
}

// ============================================
// Elevation Profile
// ============================================

/**
 * Build and display an SVG elevation profile in the measure panel.
 * Shows depth below water surface along the measured route.
 */
function updateElevationProfile() {
    const container = document.getElementById('measure-profile');
    if (!container) return;

    if (state.measureSegments.length === 0 || !state.bathymetryLayer) {
        container.classList.remove('visible');
        container.innerHTML = '';
        return;
    }

    const waterLevel = getActiveWaterLevel();

    // Sample elevation along all segments
    const samples = []; // { dist, depth }
    let cumulativeDist = 0;

    for (const seg of state.measureSegments) {
        const coords = seg.coords;
        for (let i = 0; i < coords.length; i++) {
            // For straight-line 2-point segments, interpolate additional samples
            if (i < coords.length - 1) {
                const [lng1, lat1] = coords[i];
                const [lng2, lat2] = coords[i + 1];
                const segDist = haversineDistance([lng1, lat1], [lng2, lat2]);
                const numSamples = Math.max(1, Math.ceil(segDist / 2)); // ~2m spacing

                for (let s = 0; s < numSamples; s++) {
                    const t = s / numSamples;
                    const lng = lng1 + (lng2 - lng1) * t;
                    const lat = lat1 + (lat2 - lat1) * t;
                    const elev = state.bathymetryLayer.getElevationAtLngLat(lng, lat);
                    const depth = elev !== null ? Math.max(0, waterLevel - elev) : 0;

                    if (s === 0 && samples.length > 0) continue; // skip duplicate junction point
                    samples.push({ dist: cumulativeDist + segDist * t, depth });
                }
                cumulativeDist += segDist;
            }
        }
    }

    // Add final point
    const lastCoord = state.measureSegments[state.measureSegments.length - 1].coords;
    const [fLng, fLat] = lastCoord[lastCoord.length - 1];
    const fElev = state.bathymetryLayer.getElevationAtLngLat(fLng, fLat);
    const fDepth = fElev !== null ? Math.max(0, waterLevel - fElev) : 0;
    samples.push({ dist: cumulativeDist, depth: fDepth });

    if (samples.length < 2) {
        container.classList.remove('visible');
        container.innerHTML = '';
        return;
    }

    // Compute ranges
    const totalDist = samples[samples.length - 1].dist;
    let maxDepth = 0;
    for (const s of samples) {
        if (s.depth > maxDepth) maxDepth = s.depth;
    }
    maxDepth = Math.max(maxDepth, 1); // Minimum 1m scale

    // SVG dimensions
    const svgW = 260;
    const svgH = 80;
    const margin = { top: 4, right: 8, bottom: 16, left: 28 };
    const plotW = svgW - margin.left - margin.right;
    const plotH = svgH - margin.top - margin.bottom;

    // Scale functions
    const xScale = (d) => margin.left + (d / totalDist) * plotW;
    const yScale = (d) => margin.top + (d / maxDepth) * plotH;

    // Build path
    let pathD = `M ${xScale(samples[0].dist)} ${yScale(samples[0].depth)}`;
    for (let i = 1; i < samples.length; i++) {
        pathD += ` L ${xScale(samples[i].dist)} ${yScale(samples[i].depth)}`;
    }

    // Closed fill path
    const fillD = pathD +
        ` L ${xScale(totalDist)} ${yScale(0)}` +
        ` L ${xScale(0)} ${yScale(0)} Z`;

    // Y-axis labels
    const yLabels = [];
    const yStep = maxDepth <= 5 ? 1 : maxDepth <= 15 ? 5 : 10;
    for (let d = 0; d <= maxDepth; d += yStep) {
        yLabels.push(d);
    }

    // X-axis labels
    const xLabels = [];
    const xStep = totalDist <= 50 ? 10 : totalDist <= 200 ? 50 : totalDist <= 500 ? 100 : 200;
    for (let d = 0; d <= totalDist; d += xStep) {
        xLabels.push(d);
    }

    const svg = `<svg viewBox="0 0 ${svgW} ${svgH}" xmlns="http://www.w3.org/2000/svg">
        <!-- Surface line -->
        <line class="profile-surface" x1="${margin.left}" y1="${yScale(0)}" x2="${xScale(totalDist)}" y2="${yScale(0)}"/>
        <!-- Depth fill -->
        <path class="profile-fill" d="${fillD}"/>
        <!-- Y-axis labels -->
        ${yLabels.map(d => `
            <line class="profile-axis" x1="${margin.left}" y1="${yScale(d)}" x2="${xScale(totalDist)}" y2="${yScale(d)}"/>
            <text class="profile-label" x="${margin.left - 3}" y="${yScale(d) + 3}" text-anchor="end">${d}m</text>
        `).join('')}
        <!-- X-axis labels -->
        ${xLabels.map(d => `
            <text class="profile-label" x="${xScale(d)}" y="${svgH - 2}" text-anchor="middle">${d >= 1000 ? (d / 1000).toFixed(1) + 'k' : d}m</text>
        `).join('')}
    </svg>`;

    container.innerHTML = svg;
    container.classList.add('visible');
}

// ============================================
// Depth Probe Tool
// ============================================

function initializeDepthProbe() {
    // Create desktop tooltip element
    const tooltip = document.createElement('div');
    tooltip.className = 'depth-probe-tooltip';
    document.body.appendChild(tooltip);
    state.depthProbeTooltip = tooltip;

    const probeBtn = document.getElementById('depth-probe-btn');
    const measureBtn = document.getElementById('measure-btn');

    probeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        state.depthProbeMode = !state.depthProbeMode;
        probeBtn.classList.toggle('active', state.depthProbeMode);

        if (state.depthProbeMode) {
            // Deactivate measure mode if active
            if (state.measureMode) {
                state.measureMode = false;
                measureBtn.classList.remove('active');
                document.body.classList.remove('measure-mode-active');
            }
            document.body.classList.add('depth-probe-active');
        } else {
            document.body.classList.remove('depth-probe-active');
            tooltip.style.display = 'none';
            hideDepthProbePopup();
        }

        probeBtn.blur();
    });

    // Track touch state so synthetic mousemove events don't show the desktop tooltip
    let isTouching = false;

    // Desktop: mousemove on map canvas
    map.on('mousemove', (e) => {
        if (!state.depthProbeMode || isTouching) return;
        showDepthProbeDesktop(e.lngLat, e.point);
    });

    // Hide tooltip when mouse leaves the map
    map.getCanvas().addEventListener('mouseleave', () => {
        if (state.depthProbeMode) {
            tooltip.style.display = 'none';
        }
    });

    // Mobile: touchstart/touchmove on map canvas
    const canvas = map.getCanvas();
    const handleTouch = (e) => {
        if (!state.depthProbeMode) return;
        isTouching = true;
        tooltip.style.display = 'none';
        const touch = e.touches[0];
        if (!touch) return;
        const rect = canvas.getBoundingClientRect();
        const point = new maplibregl.Point(
            touch.clientX - rect.left,
            touch.clientY - rect.top
        );
        const lngLat = map.unproject(point);
        showDepthProbePopup(lngLat);
    };

    canvas.addEventListener('touchstart', handleTouch, { passive: true });
    canvas.addEventListener('touchmove', handleTouch, { passive: true });
    canvas.addEventListener('touchend', () => {
        // Reset after a delay so the synthetic mousemove is also suppressed
        setTimeout(() => { isTouching = false; }, 300);
    }, { passive: true });
}

/**
 * Compute the depth text for a given lngLat.
 */
function getDepthText(lngLat) {
    const elev = state.bathymetryLayer
        ? state.bathymetryLayer.getElevationAtLngLat(lngLat.lng, lngLat.lat)
        : null;

    if (elev === null) return 'No data';
    const waterLevel = getActiveWaterLevel();
    if (elev > waterLevel) return 'Above water';
    return `${(waterLevel - elev).toFixed(1)}m`;
}

/**
 * Desktop: lightweight fixed-position tooltip near cursor.
 */
function showDepthProbeDesktop(lngLat, screenPoint) {
    const tooltip = state.depthProbeTooltip;
    if (!tooltip) return;

    tooltip.textContent = getDepthText(lngLat);
    tooltip.style.display = 'block';
    tooltip.style.left = `${screenPoint.x}px`;
    tooltip.style.top = `${screenPoint.y}px`;
}

/**
 * Mobile: MapLibre Popup anchored to the touch lngLat (with pointer arrow).
 */
function showDepthProbePopup(lngLat) {
    const text = getDepthText(lngLat);

    if (!state.depthProbePopup) {
        state.depthProbePopup = new maplibregl.Popup({
            closeButton: false,
            closeOnClick: false,
            className: 'depth-probe-popup',
            anchor: 'bottom'
        });
        state.depthProbePopup.addTo(map);
    }

    state.depthProbePopup
        .setLngLat(lngLat)
        .setHTML(`<span class="depth-probe-popup-text">${text}</span>`);
}

function hideDepthProbePopup() {
    if (state.depthProbePopup) {
        state.depthProbePopup.remove();
        state.depthProbePopup = null;
    }
}

// ============================================
// Contour Grid Loading (for A* drag)
// ============================================

/**
 * Async load contour source at native resolution for the bounding box
 * covering two endpoints + padding. Stores result in state.contourDragGrid.
 */
async function loadContourGridForDrag(ptA, ptB) {
    if (!state.contourTiff || !state.contourBbox) return;

    state.contourDragGridLoading = true;

    try {
        // Compute bounding box in Web Mercator with padding
        const [axM, ayM] = lngLatToWebMercator(ptA.lng, ptA.lat);
        const [bxM, byM] = lngLatToWebMercator(ptB.lng, ptB.lat);

        const minX = Math.min(axM, bxM);
        const maxX = Math.max(axM, bxM);
        const minY = Math.min(ayM, byM);
        const maxY = Math.max(ayM, byM);

        // Add 100m padding in Mercator
        const pad = 100;
        const [srcMinX, srcMinY, srcMaxX, srcMaxY] = state.contourBbox;
        const bbox = [
            Math.max(minX - pad, srcMinX),
            Math.max(minY - pad, srcMinY),
            Math.min(maxX + pad, srcMaxX),
            Math.min(maxY + pad, srcMaxY)
        ];

        if (bbox[0] >= bbox[2] || bbox[1] >= bbox[3]) {
            state.contourDragGridLoading = false;
            return;
        }

        // Read at native resolution (~1m/pixel from the contour source)
        const rasters = await state.contourTiff.readRasters({
            bbox,
            resX: 1.0,
            resY: 1.0
        });

        const rawGrid = rasters[0];
        const width = rasters.width;
        const height = rasters.height;

        // Clean NoData → NaN
        const grid = new Float32Array(rawGrid.length);
        const noDataValue = state.contourNoData;
        for (let i = 0; i < rawGrid.length; i++) {
            const val = rawGrid[i];
            if (val === noDataValue || val >= 1e5 || !Number.isFinite(val)) {
                grid[i] = Number.NaN;
            } else {
                grid[i] = val;
            }
        }

        state.contourDragGrid = { grid, width, height, bbox };
        console.log(`Contour drag grid loaded: ${width}x${height} (${(rawGrid.length * 4 / 1024).toFixed(0)}KB)`);
    } catch (error) {
        console.error('Failed to load contour drag grid:', error);
    } finally {
        state.contourDragGridLoading = false;
    }
}

// ============================================
// Click Handlers
// ============================================

function initializeClickHandlers() {
    // Vertex click handler (measure mode: route along graph)
    map.on('click', 'survey-vertices-layer', (e) => {
        if (!state.measureMode) return;
        if (state._suppressClick) return;
        if (e.features.length === 0) return;
        e.originalEvent._vertexHandled = true;
        const key = e.features[0].properties.key;
        addMeasureVertex(key);
    });

    // General map click (measure mode: free-form point)
    map.on('click', (e) => {
        if (!state.measureMode) return;
        if (state._suppressClick) return;
        if (e.originalEvent._vertexHandled) return;
        addMeasureFreePoint(e.lngLat);
    });

    // --- Drag handlers for free-form measure points ---

    // mousedown on measure point: start drag if non-vertex
    map.on('mousedown', 'measure-points-layer', (e) => {
        if (!state.measureMode) return;
        if (e.features.length === 0) return;
        const feat = e.features[0];
        if (feat.properties.isVertex) return;

        e.preventDefault();
        state.draggingPointIndex = feat.properties.index;
        state._suppressClick = true;
        map.dragPan.disable();
        map.getCanvas().style.cursor = 'grabbing';
    });

    // mousemove on map: reposition dragged point and recompute segments
    map.on('mousemove', (e) => {
        if (state.draggingPointIndex === null) return;

        const i = state.draggingPointIndex;
        const pt = state.measurePoints[i];
        pt.lng = e.lngLat.lng;
        pt.lat = e.lngLat.lat;

        // Recompute preceding segment (i-1 → i)
        if (i > 0) {
            const prev = state.measurePoints[i - 1];
            const seg = state.measureSegments[i - 1];
            seg.coords = [[prev.lng, prev.lat], [pt.lng, pt.lat]];
            seg.distance = haversineDistance([prev.lng, prev.lat], [pt.lng, pt.lat]);
        }

        // Recompute following segment (i → i+1)
        if (i < state.measurePoints.length - 1) {
            const next = state.measurePoints[i + 1];
            const seg = state.measureSegments[i];
            seg.coords = [[pt.lng, pt.lat], [next.lng, next.lat]];
            seg.distance = haversineDistance([pt.lng, pt.lat], [next.lng, next.lat]);
        }

        // Recalculate total distance
        state.measureTotalDistance = state.measureSegments.reduce((sum, s) => sum + s.distance, 0);

        updateMeasureVisualization();
        rebuildMeasurePanel();
    });

    // mouseup on window: end drag
    window.addEventListener('mouseup', () => {
        if (state.draggingPointIndex === null) return;
        state.draggingPointIndex = null;
        map.dragPan.enable();
        map.getCanvas().style.cursor = 'crosshair';
        // Clear suppress flag after the click event fires (click fires after mouseup)
        setTimeout(() => { state._suppressClick = false; }, 0);
    });

    // --- Contour drag: mousedown on measure line segment ---
    map.on('mousedown', 'measure-line-hit', (e) => {
        if (!state.measureMode) return;
        if (state.measureSegments.length === 0) return;
        if (state.draggingPointIndex !== null) return;

        // Find which segment was clicked by checking distance to each segment line
        const clickLng = e.lngLat.lng;
        const clickLat = e.lngLat.lat;
        let bestSegIdx = -1;
        let bestDist = Infinity;

        for (let si = 0; si < state.measureSegments.length; si++) {
            const seg = state.measureSegments[si];
            if (seg.contourAHD !== undefined) continue; // already a contour segment
            const coords = seg.coords;
            for (let ci = 0; ci < coords.length - 1; ci++) {
                const [ax, ay] = coords[ci];
                const [bx, by] = coords[ci + 1];
                const d = _pointToLineDistance([clickLng, clickLat], [ax, ay], [bx, by]);
                if (d < bestDist) {
                    bestDist = d;
                    bestSegIdx = si;
                }
            }
        }

        // Threshold: ~0.0001 degrees (~10m)
        if (bestSegIdx < 0 || bestDist > 0.0001) return;

        const pointAIndex = bestSegIdx;
        const pointBIndex = bestSegIdx + 1;
        const ptA = state.measurePoints[pointAIndex];
        const ptB = state.measurePoints[pointBIndex];

        // Require at least one free (non-vertex) endpoint
        if (ptA.isVertex && ptB.isVertex) return;

        e.preventDefault();
        state.draggingContourSegment = { segmentIndex: bestSegIdx, pointAIndex, pointBIndex };
        state._suppressClick = true;
        state.contourDragGrid = null;
        state.contourPreviewCoords = null;
        map.dragPan.disable();
        map.getCanvas().style.cursor = 'crosshair';

        // Async: load contour grid for bounding box of the two endpoints + padding
        loadContourGridForDrag(ptA, ptB);
    });

    // mousemove: extend to handle contour drag preview
    map.on('mousemove', (e) => {
        if (state.draggingContourSegment === null) return;

        const mouseElev = state.bathymetryLayer
            ? state.bathymetryLayer.getElevationAtLngLat(e.lngLat.lng, e.lngLat.lat)
            : null;

        if (mouseElev === null) return;

        const waterLevel = getActiveWaterLevel();
        if (mouseElev > waterLevel) return; // above water

        const targetElevation = mouseElev;

        if (state.contourDragGrid) {
            const { grid, width, height, bbox } = state.contourDragGrid;
            const { pointAIndex, pointBIndex } = state.draggingContourSegment;
            const ptA = state.measurePoints[pointAIndex];
            const ptB = state.measurePoints[pointBIndex];

            const contourPath = findContourPath(
                grid, width, height, bbox,
                ptA.lng, ptA.lat, ptB.lng, ptB.lat,
                targetElevation, 0.5
            );

            if (contourPath && contourPath.length >= 2) {
                state.contourPreviewCoords = contourPath;
                state._contourPreviewElevation = targetElevation;

                // Show preview: approach + contour + depart
                const features = [];

                // Approach line: ptA → contour start
                const contourStart = contourPath[0];
                const contourEnd = contourPath[contourPath.length - 1];

                features.push({
                    type: 'Feature',
                    geometry: { type: 'LineString', coordinates: [[ptA.lng, ptA.lat], contourStart] },
                    properties: { type: 'approach' }
                });

                // Contour path
                features.push({
                    type: 'Feature',
                    geometry: { type: 'LineString', coordinates: contourPath },
                    properties: { type: 'contour' }
                });

                // Depart line: contour end → ptB
                features.push({
                    type: 'Feature',
                    geometry: { type: 'LineString', coordinates: [contourEnd, [ptB.lng, ptB.lat]] },
                    properties: { type: 'depart' }
                });

                map.getSource('measure-contour-preview').setData({
                    type: 'FeatureCollection',
                    features
                });
            } else {
                // No path found — clear preview
                map.getSource('measure-contour-preview').setData({ type: 'FeatureCollection', features: [] });
                state.contourPreviewCoords = null;
            }
        }
    });

    // mouseup: finalize contour on release
    globalThis.addEventListener('mouseup', () => {
        if (state.draggingContourSegment === null) return;

        const { segmentIndex, pointAIndex, pointBIndex } = state.draggingContourSegment;

        if (state.contourPreviewCoords && state.contourPreviewCoords.length >= 2) {
            const contourPath = state.contourPreviewCoords;
            const targetElevation = state._contourPreviewElevation;
            const contourStart = contourPath[0];
            const contourEnd = contourPath[contourPath.length - 1];
            const ptA = state.measurePoints[pointAIndex];
            const ptB = state.measurePoints[pointBIndex];

            // Create approach segment
            const approachCoords = [[ptA.lng, ptA.lat], contourStart];
            const approachDist = haversineDistance(approachCoords[0], approachCoords[1]);

            // Create contour segment
            let contourDist = 0;
            for (let i = 0; i < contourPath.length - 1; i++) {
                contourDist += haversineDistance(contourPath[i], contourPath[i + 1]);
            }

            // Create depart segment
            const departCoords = [contourEnd, [ptB.lng, ptB.lat]];
            const departDist = haversineDistance(departCoords[0], departCoords[1]);

            // Create contour anchor points
            const anchorA = {
                lng: contourStart[0], lat: contourStart[1],
                isVertex: false, vertexKey: null, isContourAnchor: true
            };
            const anchorB = {
                lng: contourEnd[0], lat: contourEnd[1],
                isVertex: false, vertexKey: null, isContourAnchor: true
            };

            // Splice: replace 1 segment with 3
            state.measureSegments.splice(segmentIndex, 1,
                { coords: approachCoords, distance: approachDist },
                { coords: contourPath, distance: contourDist, contourAHD: targetElevation },
                { coords: departCoords, distance: departDist }
            );

            // Insert 2 anchor points after pointA (at pointBIndex position)
            state.measurePoints.splice(pointBIndex, 0, anchorA, anchorB);

            // Recalculate total distance
            state.measureTotalDistance = state.measureSegments.reduce((sum, s) => sum + s.distance, 0);
        }

        // Clear state
        state.draggingContourSegment = null;
        state.contourDragGrid = null;
        state.contourPreviewCoords = null;
        delete state._contourPreviewElevation;
        map.dragPan.enable();
        if (state.measureMode) {
            map.getCanvas().style.cursor = 'crosshair';
        }

        // Clear preview
        map.getSource('measure-contour-preview').setData({ type: 'FeatureCollection', features: [] });

        // Rebuild everything
        updateMeasureVisualization();
        rebuildMeasurePanel();
        updateElevationProfile();

        setTimeout(() => { state._suppressClick = false; }, 0);
    });

    // --- Cursor feedback ---

    // Vertices in measure mode
    map.on('mouseenter', 'survey-vertices-layer', () => {
        if (state.measureMode && state.draggingPointIndex === null) {
            map.getCanvas().style.cursor = 'pointer';
        }
    });

    map.on('mouseleave', 'survey-vertices-layer', () => {
        if (state.measureMode && state.draggingPointIndex === null) {
            map.getCanvas().style.cursor = 'crosshair';
        }
    });

    // Free-form measure points: grab cursor
    map.on('mouseenter', 'measure-points-layer', (e) => {
        if (!state.measureMode || state.draggingPointIndex !== null) return;
        if (e.features.length > 0 && !e.features[0].properties.isVertex) {
            map.getCanvas().style.cursor = 'grab';
        }
    });

    map.on('mouseleave', 'measure-points-layer', () => {
        if (state.measureMode && state.draggingPointIndex === null) {
            map.getCanvas().style.cursor = 'crosshair';
        }
    });

    // Measure line segments: ns-resize cursor for contour drag
    map.on('mouseenter', 'measure-line-hit', () => {
        if (state.measureMode && state.draggingPointIndex === null && state.draggingContourSegment === null) {
            map.getCanvas().style.cursor = 'ns-resize';
        }
    });

    map.on('mouseleave', 'measure-line-hit', () => {
        if (state.measureMode && state.draggingPointIndex === null && state.draggingContourSegment === null) {
            map.getCanvas().style.cursor = 'crosshair';
        }
    });
}

// ============================================
// Layer Controls
// ============================================

function initializeLayerControls() {
    const layerControls = document.querySelectorAll('.layer-control[data-layer]');

    layerControls.forEach(control => {
        const layerId = control.dataset.layer;
        const checkbox = control.querySelector('input[type="checkbox"]');

        checkbox.addEventListener('change', () => {
            state.layerVisibility[layerId] = checkbox.checked;
            const visibility = checkbox.checked ? 'visible' : 'none';

            if (layerId === 'bathymetry') {
                // Both bathymetry and hillshade are custom WebGL layers — use opacity
                if (state.bathymetryLayer) {
                    state.bathymetryLayer.setOpacity(checkbox.checked ? 1.0 : 0.0);
                }
                if (state.hillshadeLayer) {
                    state.hillshadeLayer.setOpacity(checkbox.checked ? 1.0 : 0.0);
                }
                map.triggerRepaint();
            } else if (layerId === 'contours') {
                if (map.getLayer('contours-layer')) {
                    map.setLayoutProperty('contours-layer', 'visibility', visibility);
                }
                if (map.getLayer('contours-labels')) {
                    map.setLayoutProperty('contours-labels', 'visibility', visibility);
                }
                if (checkbox.checked) {
                    generateContoursForViewport();
                }
            } else if (['entries', 'structures'].includes(layerId)) {
                const sourceId = `overlay-${layerId}`;
                if (map.getLayer(`${sourceId}-circles`)) {
                    map.setLayoutProperty(`${sourceId}-circles`, 'visibility', visibility);
                }
                if (map.getLayer(`${sourceId}-labels`)) {
                    map.setLayoutProperty(`${sourceId}-labels`, 'visibility', visibility);
                }
            }
        });
    });
}

// ============================================
// Mobile Toggle
// ============================================

function initializeMobileToggle() {
    const titleCard = document.querySelector('.title-card');
    const legend = document.querySelector('.legend');
    const legendToggle = document.getElementById('legend-toggle');

    titleCard.addEventListener('click', (e) => {
        if (globalThis.innerWidth <= 768) {
            if (e.target.tagName !== 'A') {
                titleCard.classList.toggle('expanded');
            }
        }
    });

    if (legendToggle && legend) {
        legendToggle.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            legend.classList.toggle('collapsed');

            const isCollapsed = legend.classList.contains('collapsed');
            localStorage.setItem('legendCollapsed', isCollapsed ? 'true' : 'false');
        });

        if (globalThis.innerWidth <= 768) {
            const savedState = localStorage.getItem('legendCollapsed');
            if (savedState === 'true') {
                legend.classList.add('collapsed');
            }
        }
    }
}

// ============================================
// Legend Zoom to Survey Line
// ============================================

function initializeLegendToggles() {
    const colorItems = document.querySelectorAll('.color-item[data-line]');

    colorItems.forEach(item => {
        item.addEventListener('click', () => {
            const lineKey = item.dataset.line;
            const surveyLine = state.surveyData[lineKey];

            if (surveyLine && surveyLine.coordinates.length > 0) {
                const lngs = surveyLine.coordinates.map(c => c[0]);
                const lats = surveyLine.coordinates.map(c => c[1]);

                const bounds = [
                    [Math.min(...lngs), Math.min(...lats)],
                    [Math.max(...lngs), Math.max(...lats)]
                ];

                const isMobile = globalThis.innerWidth <= 768;
                const padding = isMobile
                    ? { top: 120, bottom: 250, left: 50, right: 50 }
                    : { top: 100, bottom: 100, left: 400, right: 100 };

                map.fitBounds(bounds, {
                    padding: padding,
                    maxZoom: 17,
                    duration: 1000
                });

                colorItems.forEach(ci => ci.classList.remove('selected'));
                item.classList.add('selected');
            }
        });
    });
}

// ============================================
// Context Menu
// ============================================

map.on('contextmenu', (e) => {
    const existing = document.getElementById('context-menu');
    if (existing) existing.remove();

    const { lng, lat } = e.lngLat;
    const coords = formatCoordinates(lng, lat);

    const menu = document.createElement('div');
    menu.id = 'context-menu';
    menu.className = 'context-menu';
    menu.style.left = `${e.point.x}px`;
    menu.style.top = `${e.point.y}px`;

    menu.innerHTML = `
        <div class="context-menu-item" id="copy-dd">
            <span>Copy Decimal Degrees</span>
            <span style="opacity: 0.5; margin-left: 12px; font-size: 0.7rem;">${coords.gmaps}</span>
        </div>
        <div class="context-menu-separator"></div>
        <div class="context-menu-item" id="copy-dm">
            <span>Copy Decimal Minutes</span>
            <span style="opacity: 0.5; margin-left: 12px; font-size: 0.7rem;">${coords.display}</span>
        </div>
        <div class="context-menu-separator"></div>
        <div class="context-menu-item" id="copy-link">
            <span>Copy Link</span>
        </div>
    `;

    document.body.appendChild(menu);

    document.getElementById('copy-dd').addEventListener('click', () => {
        navigator.clipboard.writeText(coords.gmaps);
        menu.remove();
    });

    document.getElementById('copy-dm').addEventListener('click', () => {
        navigator.clipboard.writeText(coords.display);
        menu.remove();
    });

    document.getElementById('copy-link').addEventListener('click', () => {
        const url = `${globalThis.location.origin}${globalThis.location.pathname}#${lat.toFixed(6)},${lng.toFixed(6)}`;
        navigator.clipboard.writeText(url);
        menu.remove();
    });

    const closeMenu = () => {
        menu.remove();
        document.removeEventListener('click', closeMenu);
    };
    setTimeout(() => document.addEventListener('click', closeMenu), 100);
});

// ============================================
// Water Level Display
// ============================================

function updateWaterLevelDisplay() {
    const storageGL = getActiveStorageGL();
    const waterLevel = getActiveWaterLevel();
    const [, maxDepth] = getActiveDepthRange();

    // Update water level note
    const noteEl = document.getElementById('water-level-note');
    if (noteEl) {
        if (state.useCurrentLevel) {
            noteEl.textContent = `Water level: ~${waterLevel.toFixed(1)}m AHD (${storageGL} GL)`;
            noteEl.title = `Current level from Water Corporation (${CONFIG.WATER_LEVEL_DATE})`;
        } else {
            noteEl.textContent = `Water level: ~${waterLevel.toFixed(1)}m AHD (${storageGL} GL)`;
            noteEl.title = 'Custom water level (drag slider to adjust)';
        }
    }

    // Update depth labels based on current range
    const depthLabelsEl = document.querySelector('.depth-labels');
    if (depthLabelsEl) {
        const midDepth = Math.round(maxDepth / 2);
        depthLabelsEl.innerHTML = `<span>0m</span><span>${midDepth}m</span><span>${maxDepth}m</span>`;
    }

    // Update slider value display
    const sliderValueEl = document.getElementById('water-level-value');
    if (sliderValueEl) {
        sliderValueEl.textContent = `${Math.round(storageGL)} GL`;
    }

    // Update depth gradient
    initializeDepthGradient();
}

/**
 * Refresh bathymetry after water level change.
 * Re-colors the cached elevation data — no COG re-read needed.
 */
function refreshBathymetryTiles() {
    if (state.bathymetryLayer && state.bathymetryLayer.recolor) {
        state.bathymetryLayer.recolor();
    }

    // Clear contour cache since depths have changed
    state.contoursCache.clear();
}

/**
 * Handle water level change from slider or checkbox
 */
function onWaterLevelChange() {
    // Update UI elements
    updateWaterLevelDisplay();

    // Refresh bathymetry visualization
    refreshBathymetryTiles();

    // Regenerate contours for current view
    if (state.contourLowRes && state.layerVisibility.contours) {
        generateContoursForViewport();
    }

    // Update elevation profile (depths change with water level)
    updateElevationProfile();
}

/**
 * Initialize water level slider controls
 */
function initializeWaterLevelControls() {
    const slider = document.getElementById('water-level-slider');
    const lockCheckbox = document.getElementById('water-level-lock');
    const currentLevelLabel = document.getElementById('current-level-label');

    if (!slider || !lockCheckbox) return;

    // Set initial values
    slider.value = Math.round(CONFIG.CURRENT_STORAGE_GL);
    slider.disabled = state.useCurrentLevel;
    if (currentLevelLabel) {
        currentLevelLabel.textContent = `${CONFIG.CURRENT_STORAGE_GL} GL`;
    }

    // Slider input handler (while dragging)
    slider.addEventListener('input', () => {
        state.customStorageGL = parseFloat(slider.value);
        updateWaterLevelDisplay();
    });

    // Slider change handler (on release) - do the expensive refresh
    slider.addEventListener('change', () => {
        state.customStorageGL = parseFloat(slider.value);
        onWaterLevelChange();
    });

    // Checkbox handler
    lockCheckbox.addEventListener('change', () => {
        state.useCurrentLevel = lockCheckbox.checked;
        slider.disabled = state.useCurrentLevel;

        if (state.useCurrentLevel) {
            // Reset slider to current level
            slider.value = Math.round(CONFIG.CURRENT_STORAGE_GL);
        }

        onWaterLevelChange();
    });
}

// ============================================
// GeoJSON Overlay Layers (Entries, Features, Structures)
// ============================================

const OVERLAY_LAYERS = [
    { id: 'entries',    file: 'Entries.geojson',    color: '#e74c3c', label: 'Entries' },
    { id: 'structures', file: 'Structures.geojson', color: '#f39c12', label: 'Structures' }
];

async function loadOverlayLayers() {
    for (const layer of OVERLAY_LAYERS) {
        try {
            const response = await fetch(layer.file);
            if (!response.ok) { console.warn(`Could not load ${layer.file}`); continue; }
            const geojson = await response.json();

            // Reproject EPSG:3857 → WGS84 and filter null geometries
            const features = geojson.features
                .filter(f => f.geometry !== null)
                .map(f => ({
                    ...f,
                    geometry: {
                        type: f.geometry.type,
                        coordinates: webMercatorToLngLat(f.geometry.coordinates[0], f.geometry.coordinates[1])
                    }
                }));

            const sourceId = `overlay-${layer.id}`;
            map.addSource(sourceId, {
                type: 'geojson',
                data: { type: 'FeatureCollection', features }
            });

            // Circle layer
            map.addLayer({
                id: `${sourceId}-circles`,
                type: 'circle',
                source: sourceId,
                paint: {
                    'circle-radius': 7,
                    'circle-color': layer.color,
                    'circle-stroke-color': '#ffffff',
                    'circle-stroke-width': 2,
                    'circle-opacity': 0.9
                }
            });

            // Label layer
            map.addLayer({
                id: `${sourceId}-labels`,
                type: 'symbol',
                source: sourceId,
                layout: {
                    'text-field': ['coalesce', ['get', 'name'], ['get', 'Name'], ''],
                    'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
                    'text-size': 12,
                    'text-offset': [0, 1.5],
                    'text-anchor': 'top',
                    'text-optional': true
                },
                paint: {
                    'text-color': '#000000',
                    'text-halo-color': '#ffffff',
                    'text-halo-width': 1.5
                }
            });

            // Click popup
            map.on('click', `${sourceId}-circles`, (e) => {
                if (state.measureMode) { addMeasureFreePoint(e.lngLat); return; }
                const props = e.features[0].properties;
                const name = props.name || props.Name || 'Unnamed';
                const extra = props.Reporter ? `<div class="popup-row"><span class="popup-label">Reporter</span>${props.Reporter}</div>` : '';
                if (state.activePopup) state.activePopup.remove();
                state.activePopup = new maplibregl.Popup({ closeButton: true, maxWidth: '280px' })
                    .setLngLat(e.lngLat)
                    .setHTML(`<div class="segment-popup"><div class="popup-title">${name}</div>${extra}</div>`)
                    .addTo(map);
            });

            map.on('mouseenter', `${sourceId}-circles`, () => {
                if (!state.measureMode) map.getCanvas().style.cursor = 'pointer';
            });
            map.on('mouseleave', `${sourceId}-circles`, () => {
                if (!state.measureMode) map.getCanvas().style.cursor = '';
            });

            console.log(`Loaded overlay: ${layer.label} (${features.length} features)`);
        } catch (error) {
            console.error(`Error loading ${layer.file}:`, error);
        }
    }
}

// ============================================
// Map Load Handler
// ============================================

map.on('load', async () => {
    console.timeEnd('⏱️ SCRIPT START → map load event');
    console.time('⏱️ TOTAL MAP INITIALIZATION');
    try {
        // Initialize water level controls first
        initializeWaterLevelControls();
        initializeDepthGradient();
        updateWaterLevelDisplay();

        // Add bathymetry + hillshade layers (synchronous — just registers sources/layers)
        addBathymetryLayers();

        // Load survey lines (small CSV fetches)
        await loadSurveyLines();

        // Set up contour source/layers (synchronous, needs survey lines first for z-order)
        setupContourLayers();

        // Load GeoJSON overlay layers (Entries, Features, Structures)
        await loadOverlayLayers();

        // Initialize UI handlers
        initializeMeasureTool();
        initializeDepthProbe();
        initializeLayerControls();
        initializeClickHandlers();
        initializeLegendToggles();
        initializeMobileToggle();

        // Hide loading overlay immediately — map is interactive now
        document.getElementById('loading').classList.add('hidden');
        console.timeEnd('⏱️ TOTAL MAP INITIALIZATION');

        // Force a render frame so MapLibre draws the bathymetry tiles
        map.triggerRepaint();

        // Use requestAnimationFrame to yield to the browser before starting
        // heavy background work — this ensures the map actually paints first.
        // Start contour COG loading + initial generation in background
        // (Bathymetry and hillshade layers start loading automatically via onAdd)
        requestAnimationFrame(() => {
            console.time('⏱️ initializeContourGeneration (background)');
            initializeContourGeneration().then(() => {
                console.timeEnd('⏱️ initializeContourGeneration (background)');
            });

        });

    } catch (error) {
        console.error('Error loading map:', error);
        document.getElementById('loading-text').textContent = 'Error loading map';
    }
});
